"""
    Converts the redshift of the snapshot from text to numerical,
    in a format compatible with the file names.
    E.g. float z = 2.16 <--- str z = 'z002p160'.
    """
def redshift_str2num(z: str) -> object {
    z = z.strip('z').replace('p', '.');
    return round(float(z), 3);
}

"""
    A helper function to wrap a side effect (callee) in an expression.

    @param callee: a 0-ary function
    @param returnee: a value

    @rtype: type of returnee
    """
def call_and_return(callee: Any, returnee: Any) -> object {
    callee();
    return returnee;
}

